const FIXTURE_PATH = path.resolve(
  __dirname,
  '../../../../__fixtures__/example-todo-main',
)

beforeAll(() => {
  process.env.CEDAR_CWD = FIXTURE_PATH
})
afterAll(() => {
  delete process.env.CEDAR_CWD
})

const cleanPaths = (p: string) => {
  return ensurePosixPath(path.relative(FIXTURE_PATH, p))
}

test('generate the correct mirror types for cells', () => {
  const paths = generateMirrorCells()
  const p = paths.map(cleanPaths)

  expect(p).toMatchInlineSnapshot(`
    [
      ".cedar/types/mirror/web/src/components/NumTodosCell/index.d.ts",
      ".cedar/types/mirror/web/src/components/NumTodosTwoCell/index.d.ts",
      ".cedar/types/mirror/web/src/components/TodoListCell/index.d.ts",
      ".cedar/types/mirror/web/src/components/TodoStatusCell/index.d.ts",
    ]
  `)

  const generatedContent = fs.readFileSync(paths[0], 'utf-8')
  expect(
    // Work around issue with Vite interpreting the sourceMappingURL comment
    // inside the inline snapshot as a real source map directive
    generatedContent.replace('//# sourceMappingURL', '//_# sourceMappingURL'),
  ).toMatchInlineSnapshot(`
    "// This file was generated by CedarJS
    import * as Cell from './NumTodosCell.js'
    import type { CellProps } from '@cedarjs/web'
    import type { NumTodosCell_GetCount, NumTodosCell_GetCountVariables } from 'types/graphql'

    type SuccessType = typeof Cell.Success

    export * from './NumTodosCell.js'

    type CellInputs = CellProps<SuccessType, NumTodosCell_GetCount, typeof Cell, NumTodosCell_GetCountVariables>

    export default function (props: CellInputs): ReturnType<SuccessType>

    //_# sourceMappingURL=index.d.ts.map
    "
  `)

  const fragmentCellPath = paths.find((mirrorPath) =>
    mirrorPath.includes('TodoStatusCell'),
  )
  const fragmentCellContent = fs.readFileSync(fragmentCellPath ?? '', 'utf-8')
  expect(
    // Work around issue with Vite interpreting the sourceMappingURL comment
    // inside the inline snapshot as a real source map directive
    fragmentCellContent.replace(
      '//# sourceMappingURL',
      '//_# sourceMappingURL',
    ),
  ).toMatchInlineSnapshot(`
    "// This file was generated by CedarJS
    import * as Cell from './TodoStatusCell.js'
    import type { TodoStatusCell_todo } from 'types/graphql'

    type SuccessType = typeof Cell.Success

    export * from './TodoStatusCell.js'

    /**
     * todo is the slice of a parent Cell's query result that
     * matches this Cell's FRAGMENT. The parent spreads the fragment in its QUERY
     * and passes the fetched data object down, e.g.
     * <Cell todo={data.someField} />
     */
    type FragmentCellInputs = { todo: TodoStatusCell_todo } & Record<string, unknown>

    export default function (props: FragmentCellInputs): ReturnType<SuccessType>

    //_# sourceMappingURL=index.d.ts.map
    "
  `)
})

test('infers mirror types from a graphql() QUERY, including when FRAGMENT is exported', () => {
  const cellPath = path.join(
    __dirname,
    '__fixtures__/typed-query-cell/TypedQueryCell.tsx',
  )
  // The fixture Cell isn't part of the example project, so its mirror is
  // generated into a temporary directory instead of the project's .cedar
  const mirrorRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'cedar-mirror-'))

  try {
    const paths = getPaths()
    const mirrorPath = generateMirrorCell(cellPath, {
      ...paths,
      base: path.dirname(cellPath),
      generated: {
        ...paths.generated,
        types: { ...paths.generated.types, mirror: mirrorRoot },
      },
    })
    const generatedContent = fs.readFileSync(mirrorPath, 'utf-8')

    expect(
      generatedContent.replace('//# sourceMappingURL', '//_# sourceMappingURL'),
    ).toMatchSnapshot()
  } finally {
    fs.rmSync(mirrorRoot, { recursive: true, force: true })
  }
})

